create table sys_i18n (id varchar2(64 char) not null, create_time timestamp(6), create_user varchar2(64 char), event_comment varchar2(512 char), event_name varchar2(128 char), event_time timestamp(6), event_user varchar2(64 char), tenant_id varchar2(64 char), trx_id varchar2(64 char), deleted number(1,0) not null check (deleted in (0,1)), description varchar2(512 char), version number(19,0), code varchar2(200 char) not null, content varchar2(2000 char), locale_code varchar2(32 char) not null, module varchar2(64 char), scope varchar2(16 char) not null check (scope in ('SYSTEM','USER')), primary key (id), constraint uk_sys_i18n_locale_code_tenant unique (locale_code, code, tenant_id, deleted));
create table sys_locale (id varchar2(64 char) not null, create_time timestamp(6), create_user varchar2(64 char), event_comment varchar2(512 char), event_name varchar2(128 char), event_time timestamp(6), event_user varchar2(64 char), tenant_id varchar2(64 char), trx_id varchar2(64 char), deleted number(1,0) not null check (deleted in (0,1)), description varchar2(512 char), version number(19,0), code varchar2(32 char) not null, is_default number(1,0) not null check (is_default in (0,1)), name varchar2(64 char), sort_no number(10,0), status varchar2(16 char) not null check (status in ('ENABLED','DISABLED')), primary key (id), constraint uk_sys_locale_code_tenant unique (code, tenant_id, deleted));
create index idx_sys_i18n_code on sys_i18n (code);
